const newItems = [];

for (const item of $input.all()) {
  // Verificar si tenemos datos binarios
  const binaryPropertyName = Object.keys(item.binary || {})[0];

  if (!binaryPropertyName) {
    // No hay datos binarios
    newItems.push({
      json: {
        name: item.json.name,
        id: item.json.id,
        content: "[No hay datos binarios disponibles]",
        mimeType: item.json.mimeType
      }
    });
    continue;
  }

  try {
    // Intentar convertir los datos binarios a texto
    const binary = item.binary[binaryPropertyName];
    const content = Buffer.from(binary.data, 'base64').toString('utf-8');

    newItems.push({
      json: {
        name: item.json.name,
        id: item.json.id,
        mimeType: item.json.mimeType,
        content: content
      }
    });
  } catch (error) {
    // Si hay error, agregar información de diagnóstico
    newItems.push({
      json: {
        name: item.json.name,
        id: item.json.id,
        mimeType: item.json.mimeType,
        content: "[Error: " + error.message + "]"
      }
    });
  }
}

return {output:newItems};

